-- Daily challenges for 2026-10-16: two new themes, 365 to-dos each.
-- Generated by tools/challenges_sql.py --since 2026-10-16. The routine loads the same rows in
-- re-runnable pieces from tools/challenges_sync.py; the GitHub workflow applies this file once
-- the SUPABASE_DB_URL secret is set.

-- The templates: an upsert on slug, so a re-run keeps every id.
insert into public.challenge_templates
  (slug, title, description, category, total_days, tags, min_level, published_at)
values
  ('handling-conflict-at-work', 'Handling Conflict at Work', 'For anyone who dreads a tense coworker, a prickly email or a disagreement in a meeting. Each day is one small, practical step toward calmer, clearer conversations at work, so disagreements get settled instead of stewing.', 'Work', 365, array['Work', 'Communication', 'Assertiveness']::text[], 1, '2026-10-16T17:00:00+00:00'::timestamptz),
  ('making-music-part-of-your-day', 'Making Music Part of Your Day', 'For anyone who has let music fade into the background. Each day is one small way to listen, sing, play or move to music on purpose, so it can lift a mood, settle a busy mind or bring people together.', 'Play', 365, array['Self-Care', 'Mindfulness', 'Stress']::text[], 1, '2026-10-16T17:00:00+00:00'::timestamptz)
on conflict (slug) do update set
  title        = excluded.title,
  description  = excluded.description,
  category     = excluded.category,
  total_days   = excluded.total_days,
  tags         = excluded.tags,
  min_level    = excluded.min_level,
  published_at = excluded.published_at;

-- The bank of to-dos for each of those templates, replaced wholesale.
delete from public.challenge_days d
  using public.challenge_templates t
  where d.template_id = t.id and t.slug in ('handling-conflict-at-work', 'making-music-part-of-your-day');

